/* eslint-disable @typescript-eslint/no-explicit-any */
import {
  SmartAssemblies,
  SmartAssembly,
  SmartAssemblyStub,
  SmartAssemblyType,
} from "@eveworld/types";
import { defineChain, formatEther, getAddress } from "viem";

import { keccak256, toBytes, encodePacked, Chain } from "viem";
import { ONE_M3, SYSTEM_IDS } from "./consts";

/**
 * Takes a string or 0x address and shortens it.
 * @param string The string to be abbreviated
 * @param precision (Optional) How many characters are on either end of the abbreviated string
 * @param expanded (Optional) Boolean, if the string is returned abbreviated or not
 * @returns The abbreviated string
 */
const abbreviateAddress = (
  string?: `0x${string}` | string,
  precision = 5,
  expanded = false,
): string => {
  if (!string) return "";
  if (expanded) return string;
  if (string.length <= precision * 2) return string;
  return `${string.slice(0, precision)}...${string.slice(-precision)}`;
};

/**
 * If a given account address is the owner of a smart assembly or not
 * @param smartAssembly
 * @param account
 * @returns Boolean
 */
const isOwner = (
  smartAssembly: SmartAssembly | SmartAssemblyStub | null,
  account?: `0x${string}`,
): boolean => {
  if (!smartAssembly?.ownerId) return false;
  return getAddress(smartAssembly.ownerId) === getAddress(account ?? "");
};
const getTxUrl = (blockexplorerUrl: string, txHash: string): string => {
  return `${blockexplorerUrl}/tx/${txHash}`;
};

// Checks to make sure that state is only updated
// if strings passed are not empty
const setSmartObjectInfo = (setInfo: any, string?: string): void => {
  if (string === undefined) return;
  if (string.length === 0 || string === "") return;
  if (string.includes("\u0000")) return;
  setInfo(string);
};

const parseURL = (string: string): string => {
  if (string.includes("://")) {
    // Remove 'http' or 'https'
    return string.split("://")[1];
  } else {
    return string;
  }
};

const clickToCopy = (string: string) => {
  return navigator.clipboard.writeText(string);
};

const getInventoryItemId = (number: number): bigint => {
  return BigInt(
    keccak256(toBytes(encodePacked(["string"], [`item:${number}`]))),
  );
};

const getCommonItems = (array1: any[], array2: any[]) => {
  const commonItems: any[] = [];
  const set: Set<any> = new Set([]);

  for (let i = 0; i < array1.length; i++) {
    const value = array1[i];
    if (!set.has(value)) set.add(value);
  }
  for (let i = 0; i < array2.length; i++) {
    const value = array2[i];
    if (set.has(value)) commonItems.push(value);
  }
  return commonItems;
};

const removeTrailingZeros = (number: string) => {
  return number.replace(/(\.\d*?[1-9])0+$|\.0*$/, "$1");
};

const getEnv = (env: string, fallback: string): string => {
  if (!env) return fallback;
  return env;
};

const getVolumeM3 = (quantity: bigint, volume: bigint): number => {
  const fuelVolumeMm = Number(formatEther(quantity)) * Number(volume);
  return fuelVolumeMm / ONE_M3;
};

const formatM3 = (quantity: bigint): number => {
  return Number(quantity) / ONE_M3;
};

const getDappUrl = (
  smartAssembly: SmartAssemblyType<SmartAssemblies>,
): string => {
  if (!smartAssembly?.dappUrl) return "";

  const pattern = /^((http|https|ftp):\/\/)/;

  let url = smartAssembly.dappUrl;
  if (!pattern.test(url)) {
    url = "http://" + url;
  }

  return url;
};

const findOwnerByAddress = (
  address1: string | undefined,
  address2: string | undefined,
): boolean => {
  if (!address2 || !address1 || address1 == "" || address2 == "") return false;
  return getAddress(address1) === getAddress(address2);
};

const prepareChainConfig = (config: any): Chain => {
  const { world, erc721, erc1155, smartCharacter, eveToken, forwarder } =
    config.contracts;

  return defineChain({
    id: config.chainId,
    name: config.name,
    network: config.name,
    nativeCurrency: config.nativeCurrency,
    rpcUrls: {
      default: {
        http: [config.rpcUrls.default.http],
        webSocket: [""],
      },
      public: {
        http: [config.rpcUrls.default.http],
        webSocket: [""],
      },
    },
    blockExplorers: {
      default: {
        name: "Blockscout",
        url: config.blockExplorerUrl,
      },
    },
    contracts: {
      World: {
        address: world.address,
      },
      ERC721Proxy: {
        address: erc721?.address,
      },
      ERC1155Proxy: {
        address: erc1155?.address,
      },
      EVEToken: {
        address: eveToken.address,
      },
      ERC2771Forwarder: {
        address: forwarder.address,
      },
    },
    sourceId: config.chainId,
  });
};

const getSystemId = (
  systemIds: Record<string, `0x${string}`>,
  systemName: SYSTEM_IDS,
): `0x${string}` | undefined => {
  for (const systemId in systemIds) {
    if (systemId == systemName) {
      return systemIds[systemId];
    }
  }
  return undefined;
};

const assertAssemblyType = (
  smartAssembly: SmartAssemblyType<SmartAssemblies> | null,
  smartAssemblyType: SmartAssemblies,
): smartAssembly is SmartAssemblyType<SmartAssemblies> => {
  return smartAssembly?.assemblyType === smartAssemblyType;
};

export {
  assertAssemblyType,
  abbreviateAddress,
  clickToCopy,
  findOwnerByAddress,
  formatM3,
  getCommonItems,
  getDappUrl,
  getEnv,
  getInventoryItemId,
  getSystemId,
  getTxUrl,
  getVolumeM3,
  isOwner,
  parseURL,
  removeTrailingZeros,
  setSmartObjectInfo,
  prepareChainConfig,
};
