import React from "react";

import { SmartAssemblyType, type InventoryItem } from "@eveworld/types";
import { findOwnerByAddress, formatM3, isOwner } from "@eveworld/utils";
import EveLinearBar from "../components/EveLinearBar";
import EveScroll from "../components/EveScroll";
import { WalletClient } from "viem";

const InventoryView = React.memo(
  ({
    smartAssembly,
    walletClient,
  }: {
    smartAssembly: SmartAssemblyType<"SmartStorageUnit">;
    walletClient: WalletClient;
  }): JSX.Element => {
    if (!smartAssembly) return <></>;

    const {
      storageItems,
      ephemeralInventoryList,
      storageCapacity,
      usedCapacity,
    } = smartAssembly.inventory;

    const isEntityOwner: boolean = isOwner(
      smartAssembly,
      walletClient?.account?.address,
    );

    const playerInventory = ephemeralInventoryList.find((x) =>
      findOwnerByAddress(x.ownerId, walletClient?.account?.address),
    );

    // If owner, return persistent storage items
    // If player, return own ephemeral storage items
    const inventoryItems = isEntityOwner
      ? storageItems?.map((item: any) => {
          return item;
        })
      : playerInventory?.ephemeralInventoryItems?.map((item) => {
          return item;
        });

    const storageCap = isEntityOwner
      ? storageCapacity
      : playerInventory?.storageCapacity;
    const usedCap = isEntityOwner
      ? usedCapacity
      : playerInventory?.usedCapacity;

    return (
      <>
        <div className="Quantum-Container Title">
          {isEntityOwner ? "Storage Inventory" : "Your Inventory"}
        </div>
        <EveScroll maxHeight="260px" id="smartassembly-inventory">
          <div className="Quantum-Container text-xs flex flex-col !py-4 gap-2 min-h-full">
            {!inventoryItems || inventoryItems.length === 0 ? (
              <div>Empty</div>
            ) : (
              inventoryItems?.map((item, index) => (
                <div key={index}>
                  <InventoryItem item={item} />
                </div>
              ))
            )}
          </div>
        </EveScroll>

        <div className="Quantum-Container Title">Inventory Capacity</div>
        <div
          className="Quantum-Container text-2xs font-bold py-2"
          id="smartassembly-invcapacity"
        >
          <EveLinearBar
            nominator={formatM3(usedCap ?? BigInt(0))}
            denominator={formatM3(storageCap ?? BigInt(0))}
            label={`m3`}
          />
        </div>
      </>
    );
  },
);

const InventoryItem = ({ item }: { item: InventoryItem }) => {
  const { typeId, name, quantity } = item;

  return (
    <div className="flex flex-col w-full">
      <div className="flex w-full justify-between font-bold">
        <span>{name ?? `Item Type ${typeId}`}</span>
        <span>{quantity}</span>
      </div>
      <span className="text-2xs">ID: {typeId}</span>
    </div>
  );
};

export default InventoryView;
