import React, { useState } from "react";

import { SmartAssembly, SmartAssemblyType } from "@eveworld/types";
import { isOwner } from "@eveworld/utils";
import EveScroll from "../components/EveScroll";
import { WalletClient } from "viem";
import EveButton from "../components/EveButton";

const GateView = React.memo(
  ({
    smartAssembly,
    walletClient,
    setSelectGate,
    linkFunction,
    unlinkFunction,
  }: {
    smartAssembly: SmartAssemblyType<"SmartGate">;
    walletClient: WalletClient;
    setSelectGate: (gateId: string) => void;
    linkFunction: () => void;
    unlinkFunction: () => void;
  }): JSX.Element => {
    const [active, setActive] = useState<string | undefined>(undefined);

    if (!smartAssembly) return <></>;

    const isEntityOwner: boolean = isOwner(
      smartAssembly,
      walletClient?.account?.address,
    );

    const { gatesInRange, isLinked, destinationGate } = smartAssembly.gateLink;

    return (
      <>
        <div className="Quantum-Container Title">Gates in Range</div>
        <div className="row-span-3" id="smartassembly-gate">
          <EveScroll
            maxHeight="260px"
            classStyles="Quantum-Container !border-0"
          >
            <div className="text-xs flex flex-col gap-2 min-h-full">
              {!gatesInRange || gatesInRange.length === 0 ? (
                <div>No gates in range</div>
              ) : (
                gatesInRange?.map((gate, index) => (
                  <div key={gate.id}>
                    <GateInRange
                      gate={gate}
                      isLinked={gate.id == destinationGate}
                      isSelected={gate.id == active}
                      onSelect={() => {
                        setActive(gate.id);
                        setSelectGate(gate.id);
                      }}
                    />
                  </div>
                ))
              )}
            </div>
          </EveScroll>

          <div className="flex justify-between w-[calc(100%-1.25rem)] p-2 w-full bg-crude">
            {/* TODO: Should not be able to link if any gate is already linked.
              Should not be able to perform any action if not owner */}
            <EveButton
              typeClass={"primary"}
              disabled={
                !isEntityOwner ||
                !smartAssembly.isOnline ||
                isLinked ||
                active == undefined ||
                active == destinationGate
              }
              id="smartassembly-linkgate"
              onClick={() => linkFunction()}
            >
              LINK
            </EveButton>
            <EveButton
              typeClass={"primary"}
              disabled={
                !isLinked || !isEntityOwner || active != destinationGate
              }
              id="smartassembly-unlinkgate"
              onClick={() => (destinationGate ? unlinkFunction() : null)}
            >
              UNLINK
            </EveButton>
          </div>
        </div>
      </>
    );
  },
);

const GateInRange = ({
  gate,
  isLinked,
  isSelected,
  onSelect,
}: {
  gate: SmartAssembly;
  isLinked: boolean;
  isSelected: boolean;
  onSelect: () => void;
}) => {
  const { typeId, name, solarSystem, itemId } = gate;

  return (
    <div
      className={`flex flex-col w-full cursor-pointer ${isSelected ? "Eve-Select-Active" : null}`}
      onClick={() => onSelect()}
    >
      <div className="flex w-full justify-between font-bold">
        <span>{name ? name : `Smart Gate ${typeId}`}</span>
        <span>{isLinked ? "LINKED" : null}</span>
      </div>
      <span className="text-2xs">{itemId}</span>
      <span className="text-2xs">
        {solarSystem?.solarSystemName ?? "Solar system:"}
      </span>
    </div>
  );
};

export default GateView;
