/* eslint-disable @typescript-eslint/no-explicit-any */
import {
  ReactNode,
  createContext,
  useCallback,
  useContext,
  useState,
} from "react";
import {
  AbiItem,
  TransactionReceipt,
  WriteContractParameters,
  encodeFunctionData,
  getAbiItem,
  Hex,
  toHex,
  decodeFunctionData,
} from "viem";

import IWorld from "@eveworld/contracts/IWorld";
import { ERC2771ForwardRequest, Severity } from "@eveworld/types";
import { ERRORS, ERROR_MESSAGES, parseErrorFromMessage } from "@eveworld/utils";

import { useConnection } from "./wallet/WalletContext";
import { ContractConfig, useWorld } from "./WorldContext";
import { useSmartObject } from "./SmartObjectContext";

interface SendTxParams {
  encodedFunctionData: Hex;
  systemId: string; // Needed for metatransactions
  contractConfig?: ContractConfig | null; // Needed for getting function definition in metatransactions
  metaTxDeadline?: number; // Time in seconds after which metatx request expires
  onClose?: () => void;
}

interface Notification {
  handleSendTx: ({
    encodedFunctionData,
    systemId,
    contractConfig,
    metaTxDeadline,
    onClose,
  }: SendTxParams) => void;
  notify: (notification: {
    type: Severity;
    txHash?: string;
    message?: string;
    errorCode?: number;
  }) => void;
  notification: {
    message: string;
    txHash: string;
    severity: Severity;
    handleClose: () => void;
    isOpen: boolean;
  };
  handleClose: () => void;
}

/**
 * NotificationProvider function to manage notifications for transactions and messages.
 * @param children The children components to be wrapped by the NotificationProvider.
 * @returns ReactNode The wrapped children components with notification context.
 */
const NotificationProvider = ({ children }: { children: ReactNode }) => {
  const [isOpen, setIsOpen] = useState<boolean>(false);
  const [message, setMessage] = useState<string>("");
  const [severity, setSeverity] = useState<Severity>(Severity.Info);
  const [txHash, setTxHash] = useState<string>("");

  const { defaultNetwork, publicClient, walletClient, gatewayConfig } =
    useConnection();
  const { world, trustedForwarder } = useWorld();
  const { walletAddress } = useSmartObject();

  const handleClose = useCallback(() => {
    setIsOpen(false);
  }, []);

  /**
   * @param type  - {@link Severity}
   * @param txHash (Optional) The transaction hash, if transaction is successful
   * @param message (Optional) The message to display
   * @param errorCode (Optional) Corresponding error code
   * **/
  const notify = useCallback(
    ({
      type,
      message,
      txHash,
      errorCode,
    }: {
      type: Severity;
      message?: string;
      txHash?: string;
      errorCode?: number;
    }) => {
      setSeverity(type);
      setIsOpen(true);

      // If success, show success message and transction hash
      if (type == Severity.Success && txHash) {
        setMessage(
          `Transaction was successful. ${
            message ?? ""
          } Transaction hash: ${txHash}`,
        );
        setTxHash(txHash);
        return;
      }

      // If an error code is passed, parse and display that error
      const getErrorMessage = (code: number) => {
        return { code, message: ERROR_MESSAGES[code] };
      };

      const error = getErrorMessage(errorCode ? errorCode : 0);

      // Otherwise, show  passed message
      setMessage(message ? message : error.message);
    },
    [],
  );

  /**
   * @param encodedFunctionData Encoded function data packed by Viem. {@link https://viem.sh/docs/contract/encodeFunctionData}
   * @param systemId MUD identification of system being called
   * @param contractConfig (Optional) The instantiation of the contract if not using IWorld, such as if using custom logic
   * @param metaTxDeadline (Optional) Time in seconds after which metatx request expires
   * @param onClose (Optional) The function to call when the tx is successfully sent
   * @returns A promise of the transaction hash
   * **/
  const handleSendTx = async ({
    encodedFunctionData,
    systemId,
    contractConfig = world,
    metaTxDeadline = 100,
    onClose,
  }: SendTxParams): Promise<`0x${string}` | undefined> => {
    if (
      !walletClient?.account ||
      !publicClient ||
      !encodedFunctionData ||
      !contractConfig
    ) {
      notify({ type: Severity.Error });
      return undefined;
    }

    try {
      notify({ type: Severity.Info, message: "Transaction in progress..." });

      const { functionName, args } = decodeFunctionData({
        abi: contractConfig.abi,
        data: encodedFunctionData,
      });

      // The following functions will always be sent as metatransactions
      const metaTxSupportedFunctions = [
        "bringOnline",
        "bringOffline",
        "setDeployableMetadata",
        "linkSmartGates",
        "unlinkSmartGates",
      ];

      if (metaTxSupportedFunctions.includes(functionName)) {
        // Validates network and contract information, encodes function data,
        // and signs typed data for a transaction.
        if (!trustedForwarder || !defaultNetwork.network) {
          notify({
            type: Severity.Error,
            errorCode: ERRORS.FORWARDER_NOT_FOUND.code,
          });
          throw Error("ERC2771 forwarder contract could not be found");
        }

        if (!systemId) {
          notify({
            type: Severity.Error,
            message: "Function systemId not provided",
          });
          throw Error("Function systemId not provided");
        }

        const callFromFunction: AbiItem | undefined = getAbiItem({
          abi: IWorld.abi,
          name: "callFrom",
        });
        if (!callFromFunction) {
          notify({
            type: Severity.Error,
            errorCode: ERRORS.CALLFROM_NOT_FOUND.code,
          });
          throw Error("callFrom ABI Definition could not be found");
        }

        /** targetContract.methods.callFrom(delegator, systemId, getContractCallData).encodeABI() */
        const callFromCallData = encodeFunctionData({
          abi: [callFromFunction],
          args: [walletClient.account.address, systemId, encodedFunctionData],
        });

        /** Deadline set to 100s after latest block */
        const block = await publicClient.getBlock();
        const deadline = Number(block.timestamp) + metaTxDeadline;

        // Use random number as nonce
        const nonce = BigInt(
          ((Math.random() * 10) ^ 18).toPrecision() + Number(block.timestamp),
        );

        /** Construct Forward Request according to ERC2771ForwardRequest specification
         *  using `callFrom` world contract function */
        const worldContractRequest: ERC2771ForwardRequest = {
          from: walletClient.account.address,
          to: defaultNetwork.worldAddress, //The address of the World Contract where the logic lives
          value: 0n,
          gas: 500_000n, // hardcode it for now at a high value
          nonce: nonce,
          deadline: deadline,
          data: callFromCallData,
        };

        /** Construct the EIP-712 Standard message for structured data hashing and signing using the above worldContractRequest, sign metatransaction object with the provided payload, then forward to signing service */
        walletClient
          .signTypedData({
            account: walletClient.account.address,
            domain: {
              name: "Forwarder",
              chainId: BigInt(defaultNetwork.network.id),
              version: "1",
              verifyingContract: defaultNetwork.erc2771ForwarderAddress,
            },
            types: {
              EIP712Domain: [
                { name: "name", type: "string" },
                { name: "version", type: "string" },
                { name: "chainId", type: "uint256" },
                { name: "verifyingContract", type: "address" },
              ],
              ForwardRequest: [
                { name: "from", type: "address" },
                { name: "to", type: "address" },
                { name: "value", type: "uint256" },
                { name: "gas", type: "uint256" },
                { name: "nonce", type: "uint256" },
                { name: "deadline", type: "uint48" },
                { name: "data", type: "bytes" },
              ],
            },
            primaryType: "ForwardRequest",
            message: worldContractRequest,
          })
          .then(async (signature: `0x${string}`) => {
            if (!walletClient.account) throw Error("No wallet client found");

            /** Create a request ForwardRequestData along with the signature and send to World API */
            const { request } = await publicClient.simulateContract({
              account: walletClient.account,
              address: walletClient.account.address,
              abi: trustedForwarder.abi,
              functionName: "execute",
              args: [
                {
                  from: worldContractRequest.from,
                  to: worldContractRequest.to,
                  value: worldContractRequest.value,
                  gas: worldContractRequest.gas,
                  nonce: worldContractRequest.nonce,
                  deadline: worldContractRequest.deadline,
                  data: worldContractRequest.data,
                  signature,
                },
              ],
            });

            const metaTxbody = JSON.stringify(request.args[0], (key, value) => {
              if (typeof value === "bigint") {
                if (key === "nonce") {
                  return toHex(value);
                }
                return Number(value.toString());
              }
              return value;
            });

            fetch(`${gatewayConfig.gatewayHttp}/metatransaction`, {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
              },
              body: metaTxbody,
            })
              .then((res) => {
                switch (res.status) {
                  case 500:
                    notify({
                      type: Severity.Error,
                      message:
                        "Internal server error 500. Metatransaction not completed.",
                    });
                    break;
                  case 400:
                    notify({
                      type: Severity.Error,
                      message: "Metatransaction bad request.",
                    });
                    break;
                  case 403:
                    notify({
                      type: Severity.Error,
                      message: "Function forbidden as metatransaction.",
                    });
                    break;
                  case 201:
                    notify({
                      type: Severity.Success,
                      message: "Metatransaction sent successfully.",
                    });
                    break;
                  default:
                    notify({
                      type: Severity.Error,
                      message: "Error sending metatransaction.",
                    });
                    break;
                }
              })
              .then(() => {
                onClose && onClose();
              })
              .catch((e) => {
                notify({
                  type: Severity.Error,
                  message: "Unable to send metatransaction.",
                });
                console.error(e);
              });
          })
          .catch((e: any) => {
            const errorCode = parseErrorFromMessage(e.message);
            if (errorCode.code != ERRORS.UNKNOWN_ERROR.code) {
              notify({
                type: Severity.Warning,
                errorCode: errorCode.code,
              });
            } else {
              notify({ type: Severity.Error, message: e.message });
            }
            console.error(e, e.message);
            return undefined;
          });
        return undefined;
      } else {
        if (!contractConfig || !args || !functionName) {
          notify({
            type: Severity.Error,
            message: "Error parsing function name or arguments.",
          });
          return;
        }

        /** If not in list of approved metatx functions, direct to sign a transaction */
        const { request } = await publicClient.simulateContract({
          ...contractConfig,
          functionName,
          args,
          account: walletAddress,
        });

        const tx = await walletClient.writeContract(
          request as WriteContractParameters,
        );

        await publicClient
          .waitForTransactionReceipt({ hash: tx })
          .then((tx: TransactionReceipt) =>
            notify({ type: Severity.Success, txHash: tx.transactionHash }),
          )
          .then(() => {
            onClose && onClose();
          });
        return tx;
      }
    } catch (e: any) {
      const errorCode = parseErrorFromMessage(e.message);
      if (errorCode.code != ERRORS.UNKNOWN_ERROR.code) {
        notify({
          type: Severity.Warning,
          errorCode: errorCode.code,
        });
      } else {
        notify({ type: Severity.Error, message: e.message });
      }
      console.error(e, e.message);
      return undefined;
    }
  };

  const notification = {
    message,
    txHash,
    severity,
    handleClose,
    isOpen,
  };

  return (
    <NotificationContext.Provider
      value={{ handleSendTx, notify, handleClose, notification }}
    >
      {children}
    </NotificationContext.Provider>
  );
};

export const NotificationContext = createContext<Notification>({
  handleSendTx: () => {},
  notify: () => {},
  notification: {
    message: "",
    txHash: "",
    severity: Severity.Success,
    handleClose: () => {},
    isOpen: false,
  },
  handleClose: () => {},
});

/**
 * Custom hook to provide notification functionalities including showing messages, handling transaction states, and managing notification visibility.
 *
 * This hook utilizes the `NotificationContext` to allow components to easily access and manipulate notification states and behaviors.
 *
 * Usage:
 * ```tsx
 * const { notify, handleSendTx, handleClose, notification } = useNotification();
 * ```
 *
 * Returns:
 * - `notify`: Function to trigger a notification with specified severity, message, transaction hash, and error code.
 * - `handleSendTx`: Async function to handle sending transactions with optional custom ABI and close callback.
 * - `handleClose`: Function to close the notification.
 * - `notification`: Object containing current notification state including `message`, `txHash`, `severity`, and `isOpen`.
 *
 * Example:
 * ```tsx
 * import { useNotification } from '@eveworld/contexts';
 *
 * const MyComponent = () => {
 *   const { notify, handleSendTx, handleClose, notification } = useNotification();
 *
 *   const sendTransaction = async () => {
 *     const txRequest = {
 *       // your transaction request details
 *     };
 *     const systemId = "0x12345"
 *     await handleSendTx(txRequest, systemId, () => console.log('Transaction sent successfully'));
 *   };
 *
 *   return (
 *     <div>
 *       <button onClick={() => notify({ type: 'success', message: 'Success!' })}>
 *         Show Notification
 *       </button>
 *       <button onClick={sendTransaction}>
 *         Send Transaction
 *       </button>
 *       {notification.isOpen && (
 *         <div className={`notification ${notification.severity}`}>
 *           {notification.message}
 *           <button onClick={handleClose}>Close</button>
 *         </div>
 *       )}
 *     </div>
 *   );
 * };
 * ```
 */
export const useNotification = () => {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error("useNotification must be used within an EveWorldProvider");
  }
  return context;
};

export default NotificationProvider;
