import React, { HTMLAttributes } from "react";

import { getVolumeM3 } from "@eveworld/utils";
import { SmartAssembly } from "@eveworld/types";
import EveLinearBar from "./EveLinearBar";
import { ONE_M3 } from "@eveworld/utils";

interface SmartAssemblyFuelProps extends HTMLAttributes<HTMLElement> {
  smartAssembly: SmartAssembly | null;
}

/**
 * Component that displays information about a smart assembly, including owner, solar system, asset ID, type ID, state, and chain.
 * Calculates and displays the fuel amount in m3 using the provided fuel amount, fuel max capacity, and fuel unit volume.
 *
 * @returns JSX.Element representing the smart assembly information UI.
 */
const SmartAssemblyFuel = (props: SmartAssemblyFuelProps): JSX.Element => {
  const { className = "", smartAssembly } = props;

  if (!smartAssembly) return <></>;

  const { fuelAmount, fuelMaxCapacity, fuelUnitVolume } = smartAssembly.fuel;

  return (
    <div className={`${className}`}>
      <div className="Quantum-Container Title">Fuel</div>
      <div className="Entity-About Quantum-Container flex flex-col text-2xs font-bold py-2 row-start-4">
        <EveLinearBar
          nominator={getVolumeM3(fuelAmount, fuelUnitVolume)}
          denominator={Number(fuelMaxCapacity) / ONE_M3}
          label={`m3`}
        />
      </div>
    </div>
  );
};

export default React.memo(SmartAssemblyFuel);
