import { Logo } from "../assets";

import { SupportedWallets } from "@eveworld/types";
import React from "react";
import EveButton from "./EveButton";

const ConnectWallet = React.memo(
  ({
    handleConnect,
    availableWallets,
  }: {
    handleConnect: (preferredWallet: SupportedWallets) => void;
    availableWallets: SupportedWallets[];
  }): JSX.Element => {
    const isEveVaultInjected =
      availableWallets.includes(SupportedWallets.EVEVAULT) ||
      availableWallets.includes(SupportedWallets.ONEKEY);

    return (
      <div className="h-screen max-w-[560px] mx-auto relative flex flex-col items-center justify-center">
        <Logo className="w-[650px] m-10" />
        <div className="grid gap-2">
          {isEveVaultInjected ? (
            <EveButton
              onClick={() => handleConnect(SupportedWallets.EVEVAULT)}
              disabled={!isEveVaultInjected}
              typeClass="primary"
            >
              Connect to EVE Vault
            </EveButton>
          ) : (
            <EveButton
              typeClass="primary"
              onClick={() =>
                window.open(
                  "https://docs.evefrontier.com/EveVault/installation",
                )
              }
            >
              Please install EVE Vault
            </EveButton>
          )}

          <EveButton
            onClick={() => handleConnect(SupportedWallets.METAMASK)}
            disabled={!availableWallets.includes(SupportedWallets.METAMASK)}
            typeClass="secondary"
            id="connect-metamask"
          >
            Connect using MetaMask
          </EveButton>

          <EveButton
            typeClass="ghost"
            className="text-xl"
            onClick={() =>
              window.open("https://docs.evefrontier.com/Dapp/quick-start")
            }
          >
            EVE Frontier Docs
          </EveButton>
        </div>
      </div>
    );
  },
);

export default React.memo(ConnectWallet);
