import { ReactNode, createContext, useContext, useMemo } from "react";
import {
  getContract,
  GetContractReturnType,
  PublicClient,
  WalletClient,
  Client,
  UnionOmit,
  ReadContractParameters,
  Abi,
} from "viem";

import { IWorldAbi, ERC2771ForwarderAbi } from "@eveworld/contracts";

import { useConnection } from "./wallet/WalletContext";

export interface ContractConfig extends GetContractReturnType {
  read: {
    [key: string]: any;
  };
  abi: Abi;
}

interface World {
  world: GetContractReturnType<typeof IWorldAbi.abi, Client> | null;
  trustedForwarder: GetContractReturnType<
    typeof ERC2771ForwarderAbi,
    Client
  > | null;
}

const WorldProvider = ({ children }: { children: ReactNode }) => {
  const { defaultNetwork, publicClient, walletClient } = useConnection();

  // Instance of the IWorld contract, to be used when making calls to the chain
  const world = useMemo(
    () =>
      getContract({
        abi: IWorldAbi.abi,
        address: defaultNetwork.worldAddress,
        client: {
          public: publicClient as PublicClient,
          wallet: walletClient as WalletClient,
        },
      }),
    [defaultNetwork, walletClient],
  );

  const trustedForwarder = useMemo(
    () =>
      getContract({
        address: defaultNetwork.erc2771ForwarderAddress,
        abi: ERC2771ForwarderAbi,
        client: {
          public: publicClient as PublicClient,
          wallet: walletClient as WalletClient,
        },
      }),
    [defaultNetwork, walletClient],
  );

  return (
    <WorldContext.Provider value={{ world, trustedForwarder }}>
      {children}
    </WorldContext.Provider>
  );
};

export const WorldContext = createContext<World>({
  world: null,
  trustedForwarder: null,
});

/**
 * Custom hook to provide access to instances of the `IWorld` contract and `trustedForwarder` contract.
 *
 * This hook utilizes the `WorldContext` to allow components to easily interact with the blockchain
 * through the `IWorld` and `trustedForwarder` contracts.
 *
 * Usage:
 * ```tsx
 * const { world, trustedForwarder } = useWorld();
 * ```
 *
 * Returns:
 * - `world`: An instance of the `IWorld` contract for making calls to the blockchain.
 * - `trustedForwarder`: An instance of the `trustedForwarder` contract for handling ERC2771 forwarder logic.
 *
 * Example:
 * ```tsx
 * import { useWorld, useConnection } from '@eveworld/contexts';
 *
 * const MyComponent = () => {
 *   const { world, trustedForwarder } = useWorld();
 *   const { walletClient } = useConnection();
 *
 *   const callWorldFunction = async () => {
 *     try {
 *       const contractSimulation = await publicClient.simulateContract({
            ...world,
            functionName: "someFunction",
            args: [BigInt(someArg)],
            account: walletClient.account.address,
          });
 *       console.log('Result:', contractSimulation);
 *     } catch (error) {
 *       console.error('Error calling world function:', error);
 *     }
 *   };
 *
 *   return (
 *     <div>
 *       <button onClick={callWorldFunction}>Call World Function</button>
 *     </div>
 *   );
 * };
 * ```
 */

export const useWorld = () => {
  const context = useContext(WorldContext);
  if (!context) {
    throw new Error("useWorld must be used within an EveWorldProvider");
  }
  return context;
};

export default WorldProvider;
