import React, { useCallback, useContext } from "react";
import { styled, Alert, Snackbar, Dialog } from "@mui/material";
import { Severity, ChainConfig } from "@eveworld/types";
import { Close, AlertIcon, Tick } from "../assets";

import { getTxUrl } from "@eveworld/utils";

import "../styles-ui.css";

/**
 * React component for displaying styled alerts with different severity levels.
 *
 * @param severity The severity level of the alert (Error, Warning, Info, Success).
 * @param isOpen Boolean indicating if the alert is open.
 * @param handleClose Function to handle closing the alert.
 * @param message The message to be displayed in the alert.
 * @param isStyled Boolean indicating if the alert should be styled.
 * @param txHash Optional transaction hash for Success alerts.
 * @returns JSX.Element representing the styled alert component.
 */
const EveAlert = React.memo(
  ({
    defaultNetwork,
    severity,
    isOpen,
    handleClose,
    message,
    isStyled,
    txHash,
  }: {
    defaultNetwork: ChainConfig;
    severity: Severity;
    isOpen: boolean;
    handleClose: () => void;
    message: string;
    isStyled: boolean;
    txHash?: string;
  }): JSX.Element => {
    const severityIcon = {
      error: {
        icon: <AlertIcon className="w-4 h-4 p-2 relative" />,
        color: "#FFFFD6",
        bgcolor: "#0C27D8",
      },
      warning: {
        icon: <AlertIcon className="w-4 h-4 p-2 relative" />,
        color: "#FFFFD6",
        bgcolor: "#0C27D8",
      },
      info: {
        icon: <AlertIcon className="w-4 h-4 p-2 relative" />,
        color: "#130904",
        bgcolor: "#FFFFD6",
      },
      success: {
        icon: <Tick className="w-4 h-4 p-2 relative" />,
        color: "#130904",
        bgcolor: "#FFFFD6",
      },
    };

    const CustomAlert = styled(Alert)(({ severity }) => ({
      margin: "8px",
      padding: "0px",
      fontFamily: "Bai Jamjuree",
      fontWeight: "400",
      fontSize: "0.875rem",
      width: "100%",
      minWidth: "400px",
      ...(severity === Severity.Warning && {
        color: "var(--main-neutral, #FFFFD6) !important",
        "& #message-box": {
          backgroundColor: "hsla(232, 89%, 45%, 1)",
        },
      }),
      ...(severity === Severity.Error && {
        color: "var(--main-neutral, #FFFFD6) !important",
        "& #message-box": {
          backgroundColor: "hsla(232, 89%, 45%, 1)",
        },
      }),
      ...(severity === Severity.Info && {
        color: "var(--main-crude, #130904) !important",
        "& #message-box": {
          backgroundColor: "var(--neutral-80, rgba(255, 255, 214, 0.80))",
        },
      }),
      ...(severity === Severity.Success && {
        color: "var(--main-crude, #130904) !important",
        "& #message-box": {
          backgroundColor: "var(--neutral-80, rgba(255, 255, 214, 0.80))",
        },
      }),
      "& .MuiAlert-message": {
        padding: 0,
        width: "100%",
      },
      "& #message-box-container, & #message-box": {
        width: "100%",
      },
    }));

    const CustomDialog = styled(Dialog)(() => ({
      "& .MuiAlert-root": {
        margin: 0,
      },
      "& div.MuiPaper-root.MuiPaper-rounded": {
        borderRadius: 0,
      },
    }));

    const styledEveAlert = useCallback(() => {
      return (
        <CustomAlert severity={severity} icon={false}>
          <div className="w-full flex-col justify-start items-center inline-flex ">
            <div
              className="self-stretch pl-2 bg-stone-950/30 justify-between items-center inline-flex"
              id="alert-bar"
            >
              <div className="justify-start items-center gap-2 flex">
                <span className="text-center text-header text-opacity-50">
                  Status:{" "}
                </span>
                <span className="text-center text-header text-opacity-80">
                  {severity}
                </span>
              </div>
              <div
                className="w-6 p-1 border border-orange-100/50 justify-center items-center gap-2 flex cursor-pointer"
                onClick={handleClose}
              >
                <Close className="w-4 h-4 relative" />
              </div>
            </div>
            <div
              className="p-1 border border-orange-100/50 flex-col justify-start items-start flex"
              onClick={() => {
                if (severity === Severity.Success && txHash) {
                  window.open(
                    getTxUrl(
                      defaultNetwork.network?.blockExplorers?.default.url ?? "",
                      txHash,
                    ),
                  );
                }
              }}
              id="message-box-container"
            >
              <div
                className={`p-6 border border-orange-100/30 justify-center items-start gap-2 inline-flex`}
                id="message-box"
              >
                <div
                  className={`w-6 h-6 bg-crude-50 border ${severityIcon[`${severity}`].color} justify-center items-center gap-2 flex`}
                >
                  {severityIcon[`${severity}`].icon}
                </div>
                <div className="flex-col justify-start items-start gap-4 inline-flex">
                  <div className="text-center" id="message-text">
                    {message}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </CustomAlert>
      );
    }, [message, message, txHash]);

    // If using Info or Success, styled alert should be wrapped in Modal instead of Snackbar
    if (
      (isStyled && severity === Severity.Info) ||
      (isStyled && severity === Severity.Success)
    ) {
      return (
        <CustomDialog open={isOpen} onClose={handleClose}>
          {styledEveAlert()}
        </CustomDialog>
      );
    }

    const isSevere =
      severity === Severity.Error || severity === Severity.Warning;

    return (
      <Snackbar
        anchorOrigin={{ vertical: "top", horizontal: "center" }}
        sx={{ top: "4.5rem !important" }}
        open={isOpen}
        onClose={() => (isSevere ? null : handleClose())}
        id="eve-alert"
      >
        {isStyled ? (
          styledEveAlert()
        ) : (
          <Alert
            severity={severity}
            icon={false}
            sx={{
              width: "100%",
              maxWidth: "80vw",
              color: severityIcon[`${severity}`].color,
              bgcolor: severityIcon[`${severity}`].bgcolor,
              fontFamily: "Sometype Mono",
              fontWeight: 700,
              fontSize: "0.875rem",
              boxShadow: 0,
              borderRadius: 0,
              p: 2,
            }}
            onClick={() => {
              if (severity === Severity.Success && txHash) {
                window.open(
                  getTxUrl(
                    defaultNetwork.network?.blockExplorers?.default.url ?? "",
                    txHash,
                  ),
                );
              }
            }}
          >
            {isSevere && <AlertIcon className="text-neutral h-4 w-4 mr-2" />}
            {message}
            {isSevere ? (
              <Close
                onClick={handleClose}
                className="Close cursor-pointer border border-neutral h-6 min-w-6 self-start p-1 hover:bg-neutral ml-6 hover:text-[#0C27D8] hover:border-[#0C27D8]"
              />
            ) : null}
          </Alert>
        )}
      </Snackbar>
    );
  },
);

export default React.memo(EveAlert);
