import { SmartAssembly } from "@eveworld/types";
import EveLoadingAnimation from "./EveLoadingAnimation";
import React from "react";

import "../styles-ui.css";

export enum ErrorNoticeTypes {
  "SMART_ASSEMBLY",
  "MESSAGE",
}
/**
 * Renders an error notice component based on the provided type.
 *
 * @param {ErrorNoticeTypes} type - The type of error notice to render (ENVIRONMENT or SMART_ASSEMBLY).
 * @returns {JSX.Element} The JSX element representing the error notice component.
 */
const ErrorNotice = React.memo(
  ({
    type,
    errorMessage,
    loading,
    smartAssembly,
  }: {
    type?: ErrorNoticeTypes;
    errorMessage?: string;
    loading?: boolean;
    smartAssembly?: SmartAssembly | null;
  }) => {
    let message;
    const noSmartAssemblyDefined = loading && !smartAssembly;

    switch (type) {
      case ErrorNoticeTypes.SMART_ASSEMBLY:
        // TODO: Blockchain gateway must differentiate between SSU undefined and SSU not found
        if (noSmartAssemblyDefined) {
          // Unit undefined
          message = "Please define a smart assembly to search for.";
        } else {
          // Unit not found
          message = `! Smart storage unit not found !`;
        }
        break;
      case ErrorNoticeTypes.MESSAGE:
        message = errorMessage;
        break;
      default:
        message = errorMessage;
        break;
    }

    return (
      <div className="Absolute-Center h-full flex items-center justify-center w-full mx-0 h-full">
        <EveLoadingAnimation position="horizontal">
          <div className="translate-y-0 mx-auto top-0 m-6 max-w-2/3 border border-brightquantum">
            <div
              className="text-crude uppercase m-2 bg-brightquantum text-center font-bold p-2"
              id="error-notice"
            >
              {message}
            </div>
          </div>
        </EveLoadingAnimation>
      </div>
    );
  },
);

export default React.memo(ErrorNotice);
