import React from "react";

import { SmartAssemblyType } from "@eveworld/types";
import { isOwner } from "@eveworld/utils";
import EveScroll from "../components/EveScroll";
import { WalletClient } from "viem";

const TurretView = React.memo(
  ({
    smartAssembly,
    walletClient,
  }: {
    smartAssembly: SmartAssemblyType<"SmartTurret">;
    walletClient: WalletClient;
  }): JSX.Element => {
    if (!smartAssembly) return <></>;

    const isEntityOwner: boolean = isOwner(
      smartAssembly,
      walletClient?.account?.address,
    );

    return (
      <>
        <div className="Quantum-Container Title">
          {isEntityOwner ? "Storage Inventory" : "Your Inventory"}
        </div>
        <EveScroll maxHeight="260px">
          <div className="Quantum-Container text-xs flex flex-col !py-4 gap-2 min-h-full"></div>
        </EveScroll>
      </>
    );
  },
);

export default TurretView;
