import React, { ReactNode } from "react";
import NotificationProvider from "./NotificationContext";
import SmartObjectProvider from "./SmartObjectContext";
import WalletProvider from "./wallet/WalletContext";
import WorldProvider from "./WorldContext";

/**
 * Provides the context for EveWorld by wrapping the components with WalletProvider, WorldProvider, SmartObjectProvider, and NotificationProvider.
 * @param children - The child components to be wrapped by the context providers.
 * @returns The wrapped components with the EveWorld context.
 */
const EveWorldProvider = ({ children }: { children: ReactNode }) => {
  return (
    <WalletProvider>
      <WorldProvider>
        <SmartObjectProvider>
          <NotificationProvider>{children}</NotificationProvider>
        </SmartObjectProvider>
      </WorldProvider>
    </WalletProvider>
  );
};

export default EveWorldProvider;
