import {
  ReactNode,
  useState,
  createContext,
  useEffect,
  useRef,
  useContext,
} from "react";

import {
  QueryParams,
  SmartCharacter,
  SmartAssemblyType,
  SmartAssemblies,
} from "@eveworld/types";

import { useConnection } from "./wallet/WalletContext";

export interface SmartObjectContextType {
  smartCharacter: SmartCharacter;
  smartAssembly: SmartAssemblyType<SmartAssemblies> | null;
  loading: boolean;
  walletAddress: `0x${string}`;
}

interface WsFeed {
  smartCharacter: SmartCharacter;
  smartAssembly: SmartAssemblyType<SmartAssemblies> | null;
}

/**
 * SmartObjectProvider component provides context for smart objects data including smart character and smart assembly.
 * It fetches data from the blockchain gateway websocket server based on the selected smart object ID.
 *
 * @param children ReactNode - The child components to be rendered within the SmartObjectProvider.
 * @returns JSX.Element - The JSX element containing the SmartObjectContext.Provider with smart object data context.
 */
const SmartObjectProvider = ({ children }: { children: ReactNode }) => {
  const [smartCharacter, setSmartCharacter] = useState<SmartCharacter>({
    address: "0x",
    id: "0",
    name: "name",
    isSmartCharacter: false,
    eveBalanceWei: Number(0),
    gasBalanceWei: Number(0),
    image: "name",
    smartAssemblies: [],
  });
  const [selectedId, setSelectedId] = useState<string>("0x");
  const [loading, setLoading] = useState<boolean>(true);
  const [walletAddress, setWalletAddress] = useState<`0x${string}`>("0x");

  const { walletClient, gatewayConfig, connectedProvider, defaultNetwork } =
    useConnection();

  const selectedEntityRef = useRef<SmartAssemblyType<SmartAssemblies> | null>(
    null,
  );

  useEffect(() => {
    // On load, check if a smart object ID exists in the .env file.
    const smartObjectId = import.meta.env.VITE_SMARTASSEMBLY_ID;

    if (smartObjectId) {
      return setSelectedId(smartObjectId);
    }

    // If nothing in .env, check if a smart object has been passed via query param.
    const queryParams = new URLSearchParams(window.location.search);
    const querySmartObjectId = queryParams.get(QueryParams.SMART_OBJECT_ID);

    if (querySmartObjectId) {
      setSelectedId(querySmartObjectId);
    }
  }, []);

  useEffect(() => {
    if (!walletClient?.account?.address || !gatewayConfig.gatewayWs) return;

    // Set up websocket feed
    const walletAddress: string = walletClient?.account?.address;
    let ws: WebSocket;

    const connectWebSocket = () => {
      if (!defaultNetwork.network) return setLoading(false);

      ws = new WebSocket(
        `${gatewayConfig.gatewayWs}/ws/${walletAddress}/${selectedId}`,
      );

      ws.onopen = () => {
        console.log("Connected to Blockchain Gateway websocket server");
        setWalletAddress((walletAddress as `0x${string}`) ?? "0x");
      };

      ws.onmessage = (event) => {
        // Handle incoming messages, update state, etc.
        const data: WsFeed = JSON.parse(event.data);
        if (data.smartCharacter) {
          setSmartCharacter(data.smartCharacter);
        }
        if (data.smartAssembly) {
          selectedEntityRef.current = {
            ...data.smartAssembly,
          };
        } else {
          selectedEntityRef.current = null;
        }
        setLoading(false);
      };

      ws.onclose = () => {
        console.log("WebSocket connection closed unexpectedly");
        // Reconnect if ws connection closes
        setTimeout(() => {
          connectWebSocket();
        }, 3000); // Reconnect after 3 seconds
      };

      ws.onerror = (error) => {
        setLoading(false);
        console.error("WebSocket error:", error);
        throw new Error("Unable to connect to websocket");
      };
    };

    connectWebSocket();

    return () => {
      if (ws) {
        ws.close();
      }
    };
  }, [
    walletClient?.account?.address,
    selectedId,
    gatewayConfig,
    connectedProvider,
  ]);

  const smartAssembly = selectedEntityRef.current;

  return (
    <SmartObjectContext.Provider
      value={{
        smartCharacter,
        smartAssembly,
        loading,
        walletAddress,
      }}
    >
      {children}
    </SmartObjectContext.Provider>
  );
};

export const SmartObjectContext = createContext<SmartObjectContextType>({
  smartCharacter: {
    address: "0x",
    id: "0",
    name: "name",
    isSmartCharacter: false,
    eveBalanceWei: Number(0),
    gasBalanceWei: Number(0),
    image: "name",
    smartAssemblies: [],
  },
  smartAssembly: null,
  loading: true,
  walletAddress: "0x",
});

/**
 * Custom hook to provide access to smart object data, including smart character and smart assembly,
 * from the SmartObjectContext. It fetches data from the blockchain gateway websocket server
 * based on the selected smart object ID.
 *
 * This hook utilizes the `SmartObjectContext` to allow components to easily access smart object data,
 * loading state, and any other related functionalities.
 *
 * Usage:
 * ```tsx
 * const { smartCharacter, smartAssembly, loading } = useSmartObject();
 * ```
 *
 * Returns:
 * - `smartCharacter`: An object containing smart character data such as address, id, name, balance, and more.
 * - `smartAssembly`: The selected smart assembly.
 * - `loading`: A boolean indicating if the data is currently being loaded.
 *
 * Example:
 * ```tsx
 * import { useSmartObject } from '@eveworld/contexts';
 *
 * const MyComponent = () => {
 *   const { smartCharacter, smartAssembly, loading } = useSmartObject();
 *
 *   if (loading) {
 *     return <div>Loading...</div>;
 *   }
 *
 *   return (
 *     <div>
 *       <h1>Smart Character: {smartCharacter.name}</h1>
 *       <p>Address: {smartCharacter.address}</p>
 *       <p>ID: {smartCharacter.id}</p>
 *       <p>Balance: {smartCharacter.eveBalanceWei}</p>
 *       {smartAssembly && (
 *         <div>
 *           <h2>Smart Assembly</h2>
 *           <p>ID: {smartAssembly.id}</p>
 *         </div>
 *       )}
 *     </div>
 *   );
 * };
 * ```
 */
export const useSmartObject = () => {
  const context = useContext(SmartObjectContext);
  if (!context) {
    throw new Error("useSmartObject must be used within an EveWorldProvider");
  }
  return context;
};

export default SmartObjectProvider;
