/**
 * Defines additional modules based on the type of smart assembly.
 * @typeparam T - Type of smart assembly ('SmartStorageUnit', 'SmartTurret', 'SmartGate')
 * @returns Additional modules specific to the smart assembly type.
 */

export type SmartAssemblies = "SmartStorageUnit" | "SmartTurret" | "SmartGate"

type AdditionalModules<T extends SmartAssemblies> =
  T extends 'SmartStorageUnit' ? {
    inventory: InventoryModule;
  } :
  T extends 'SmartTurret' ? {
    proximity: ProximityModule;
  } :
  T extends 'SmartGate' ? {
    gateLink: LinkModule;
  } :
  never;

export interface SmartAssemblyProperties<T extends SmartAssemblies> extends SmartAssembly {
  assemblyType: T;
}

export type SmartAssemblyType<T extends SmartAssemblies> = SmartAssemblyProperties<T> & AdditionalModules<T>

